def classify_recipe(r):
    if r.verify_time >= r.cook_time:
        return 'IMPOSSIBLE'
    elif r.cook_time <= 2 * r.verify_time:
        return 'EASY'
    elif r.cook_time <= 4 * r.verify_time:
        return 'MODERATE'
    else:
        return 'HARD'

def sequential_compose(r1, r2):
    return Recipe(cook_time=r1.cook_time + r2.cook_time,
                  verify_time=r1.verify_time + r2.verify_time,
                  destructive=r1.destructive or r2.destructive)

def find_reduction(r1, r2):
    cook_oh = max(0, r1.cook_time - r2.cook_time)
    verify_oh = max(0, r1.verify_time - r2.verify_time)
    return max(cook_oh, verify_oh)
